// Pseudocode explaining Steps of GC
public class GCProcess {
    public void runGC() {
        // Step 1: Stop-The-World
        // (Application threads paused)

        // Step 2: Mark Phase
        // Traverse from GC Roots and mark all reachable objects
        markReachableObjects();

        // Step 3: Sweep Phase
        // Remove unmarked objects from Heap
        sweepUnmarkedObjects();

        // Step 4: Resume Application
    }
}
